        \item[(3)] $\gamma_{D^j}^i\wedge \gamma_{D^i}^j=0$ 
        \item[(4)] $\gamma_{\mathcal{C}}^i\wedge \gamma_{\mathcal{C}}^j=\gamma_{\mathcal{C}}^i\wedge \gamma_{D^i}^j+ \gamma_{D^j}^i\wedge\gamma_{\mathcal{C}}^j$ 
    \end{itemize}

